//! Base-commit LDE workflow experiment (12 x 16-thread pinned): the current
//! pipeline — hypercube->monomial transform (3 sweeps per column), then per
//! coset the fused scale+bit-reverse+copy sweep, the block-local phase and
//! two radix-16 global sweeps of the DIT kernel (natural-order output) —
//! against a DIF (natural-order input, BIT-REVERSED output per coset)
//! pipeline: no bit-reversal pass, the coset scaling applied at the first
//! sweep's load (power chains, no tables), twiddles of the global sweeps
//! generated by power chains, two radix-16 global sweeps + one block-local
//! sweep per coset. Two DIF variants: transform separate (3 + 2x3 = 9
//! sweeps per column) and "top-4 fused" (variables 0..19 transformed by a
//! partial transform, the top four folded into the first sweep in registers:
//! 2 + 2x3 = 8 sweeps per column; the current pipeline is 11). A DIF stage's
//! twiddle depends on the lower index bits, so lower-variable transforms
//! cannot be deferred past it — only the top variables of a sweep fuse.
//! Both variants are verified against the current pipeline (bit-reversed).
#![feature(allocator_api)]

#[cfg(not(all(target_arch = "x86_64", target_feature = "avx2")))]
fn main() {
    eprintln!("x86-64 + avx2 only");
}

#[cfg(all(target_arch = "x86_64", target_feature = "avx2"))]
mod imp {
    use core::arch::x86_64::*;
    use fft::baby_bear_avx2::{avx2, balanced_chunk, spawn_chunk, Avx2TwiddleExt};
    use field::baby_bear::base::BabyBearField as F;
    use field::{Field, PrimeField};
    use prover::gkr::whir::hypercube_to_monomial::{
        multivariate_hypercube_evals_into_coeffs_avx2_bb_parallel as transform_parallel,
        multivariate_hypercube_evals_into_coeffs_avx2_bb_parallel_partial as transform_partial,
    };
    use std::alloc::Global;
    use worker::Worker;

    pub const LOG_N: u32 = 24;
    pub const N: usize = 1 << LOG_N;
    const BLOCK_LOG2: u32 = 16;

    #[inline(always)]
    unsafe fn ld(p: *const u32) -> __m256i {
        _mm256_loadu_si256(p as *const __m256i)
    }
    #[inline(always)]
    unsafe fn st(p: *mut u32, v: __m256i) {
        _mm256_storeu_si256(p as *mut __m256i, v)
    }
    #[inline(always)]
    unsafe fn bc(x: u32) -> __m256i {
        _mm256_set1_epi32(x as i32)
    }

    /// The GS / DIF butterfly `(lo + hi, (lo - hi) * w)`.
    #[inline(always)]
    unsafe fn bfly(lo: __m256i, hi: __m256i, w: __m256i) -> (__m256i, __m256i) {
        (avx2::add(lo, hi), avx2::mont_mul(avx2::sub(lo, hi), w))
    }

    /// Per-size constants of the DIF pipeline for one coset offset.
    pub struct DifTables {
        /// `sigma[k] = offset^(2^k)`, raw Montgomery
        pub sigma: [u32; 24],
        /// `omega_{2^(k+1)}` (the stage-k group root) as a field element, for the chains
        pub omega: [F; 24],
        /// small-stage twiddle tables: `tab[k][j] = omega_{2^(k+1)}^j`, `j < 2^k`, for `k <= 15`
        pub tab: Vec<Vec<u32>>,
        /// 16th / 8th / 4th roots (raw): `c16[m] = omega_16^m` etc.
        pub c16: [u32; 8],
        pub c8: [u32; 4],
        pub c4: [u32; 2],
        /// `offset^(m * 2^20)` for the load-time scaling of the first sweep (`m < 16`)
        pub part_scale: [u32; 16],
        pub offset: F,
    }

    impl DifTables {
        pub fn new(offset: F) -> Self {
            let mut sigma = [0u32; 24];
            let mut s = offset;
            for k in 0..24 {
                sigma[k] = s.raw_u32_value();
                let t = s;
                s.mul_assign(&t);
            }
            let mut omega = [F::ONE; 24];
            for k in 0..24 {
                omega[k] = fft::domain_generator_for_size::<F>(1u64 << (k + 1));
            }
            let mut tab = Vec::new();
            for k in 0..=15 {
                let mut t = Vec::with_capacity(1 << k);
                let mut x = F::ONE;
                for _ in 0..(1 << k) {
                    t.push(x.raw_u32_value());
                    x.mul_assign(&omega[k]);
                }
                tab.push(t);
            }
            let roots = |m: usize, cnt: usize| -> Vec<u32> {
                let w = fft::domain_generator_for_size::<F>(m as u64);
                let mut v = Vec::new();
                let mut x = F::ONE;
                for _ in 0..cnt {
                    v.push(x.raw_u32_value());
                    x.mul_assign(&w);
                }
                v
            };
            let c16v = roots(16, 8);
            let c8v = roots(8, 4);
            let c4v = roots(4, 2);
            let mut part_scale = [0u32; 16];
            let mut base = F::ONE;
            let mut step = offset;
            for _ in 0..20 {
                let t = step;
                step.mul_assign(&t);
            } // step = offset^(2^20)
            for m in 0..16 {
                part_scale[m] = base.raw_u32_value();
                base.mul_assign(&step);
            }
            Self {
                sigma,
                omega,
                tab,
                c16: c16v.try_into().unwrap(),
                c8: c8v.try_into().unwrap(),
                c4: c4v.try_into().unwrap(),
                part_scale,
                offset,
            }
        }
    }

    /// One radix-16 DIF global sweep (stages of strides `s, s/2, s/4, s/8`,
    /// `s = 2^k`) over line items `(group, jl)`: a group of size `2s` holds
    /// 16 sub-blocks of `s/8` elements; item `jl` is the 64-byte line
    /// `j = 16*jl` of every sub-block. Twiddles come from power chains:
    /// `t = omega_{2s}^j` (advanced by `omega^8` per vector), the four stages
    /// using `t*c16[m]`, `t^2*c8[m]`, `t^4*c4[m]`, `t^8`. With `SCALE_LOAD`
    /// (first sweep of the transform-separate variant) every loaded element
    /// is multiplied by `offset^i` (chain over `j`, constants per sub-block).
    unsafe fn dif_radix16_items<const SCALE_LOAD: bool, const TOP_T: bool>(
        a: *mut u32,
        k: usize,
        tb: &DifTables,
        item_range: core::ops::Range<usize>,
    ) {
        let s = 1usize << k;
        let sub = s / 8;
        let lines_per_group = sub / 16;
        let c16: [__m256i; 8] = core::array::from_fn(|m| bc(tb.c16[m]));
        let c8: [__m256i; 4] = core::array::from_fn(|m| bc(tb.c8[m]));
        let c4: [__m256i; 2] = core::array::from_fn(|m| bc(tb.c4[m]));
        let omega = tb.omega[k]; // omega_{2s}
        let omega8 = {
            let mut x = omega;
            for _ in 0..3 {
                let t = x;
                x.mul_assign(&t);
            }
            x
        };
        let step8 = bc(omega8.raw_u32_value());
        let part_scale: [__m256i; 16] = core::array::from_fn(|m| bc(tb.part_scale[m]));
        let off8 = {
            let mut x = tb.offset;
            for _ in 0..3 {
                let t = x;
                x.mul_assign(&t);
            }
            bc(x.raw_u32_value())
        };
        let mut t = item_range.start;
        while t < item_range.end {
            let g = t / lines_per_group;
            let jl = t % lines_per_group;
            let run = (lines_per_group - jl).min(item_range.end - t);
            let mut j = jl * 16;
            // chain starts: omega^j and offset^j for the run
            let mut tw_vec = {
                let mut x = omega.pow(j as u32);
                let mut lanes = [0u32; 8];
                for l in 0..8 {
                    lanes[l] = x.raw_u32_value();
                    x.mul_assign(&omega);
                }
                ld(lanes.as_ptr())
            };
            let mut sc_vec = if SCALE_LOAD {
                let mut x = tb.offset.pow(j as u32);
                let mut lanes = [0u32; 8];
                for l in 0..8 {
                    lanes[l] = x.raw_u32_value();
                    x.mul_assign(&tb.offset);
                }
                ld(lanes.as_ptr())
            } else {
                _mm256_setzero_si256()
            };
            let base = g * 2 * s;
            for _ in 0..run {
                for half in 0..2 {
                    let jj = j + 8 * half;
                    let mut x: [__m256i; 16] =
                        core::array::from_fn(|m| ld(a.add(base + m * sub + jj)));
                    if TOP_T {
                        // transform of the four top variables (sub-block index
                        // bits): `hi -= lo` per bit, before any scaling
                        for b in 0..4 {
                            let bit = 1usize << b;
                            for m in 0..16 {
                                if m & bit != 0 {
                                    x[m] = avx2::sub(x[m], x[m ^ bit]);
                                }
                            }
                        }
                    }
                    if SCALE_LOAD {
                        for m in 0..16 {
                            x[m] = avx2::mont_mul(avx2::mont_mul(x[m], sc_vec), part_scale[m]);
                        }
                        sc_vec = avx2::mont_mul(sc_vec, off8);
                    }
                    let t1 = tw_vec;
                    let t2 = avx2::mont_mul(t1, t1);
                    let t4 = avx2::mont_mul(t2, t2);
                    let t8 = avx2::mont_mul(t4, t4);
                    // stage stride s: pairs (m, m+8), twiddle t * c16[m]
                    for m in 0..8 {
                        let w = if m == 0 {
                            t1
                        } else {
                            avx2::mont_mul(t1, c16[m])
                        };
                        let (lo, hi) = bfly(x[m], x[m + 8], w);
                        x[m] = lo;
                        x[m + 8] = hi;
                    }
                    // stage s/2: within each half, pairs (m, m+4), twiddle t^2 * c8[m mod 4]
                    for h in [0usize, 8] {
                        for m in 0..4 {
                            let w = if m == 0 {
                                t2
                            } else {
                                avx2::mont_mul(t2, c8[m])
                            };
                            let (lo, hi) = bfly(x[h + m], x[h + m + 4], w);
                            x[h + m] = lo;
                            x[h + m + 4] = hi;
                        }
                    }
                    // stage s/4: within each quarter, pairs (m, m+2), twiddle t^4 * c4[m mod 2]
                    for q in [0usize, 4, 8, 12] {
                        for m in 0..2 {
                            let w = if m == 0 {
                                t4
                            } else {
                                avx2::mont_mul(t4, c4[m])
                            };
                            let (lo, hi) = bfly(x[q + m], x[q + m + 2], w);
                            x[q + m] = lo;
                            x[q + m + 2] = hi;
                        }
                    }
                    // stage s/8: pairs (m, m+1), twiddle t^8
                    for p in 0..8 {
                        let (lo, hi) = bfly(x[2 * p], x[2 * p + 1], t8);
                        x[2 * p] = lo;
                        x[2 * p + 1] = hi;
                    }
                    for m in 0..16 {
                        st(a.add(base + m * sub + jj), x[m]);
                    }
                    tw_vec = avx2::mont_mul(tw_vec, step8);
                }
                j += 16;
            }
            t += run;
        }
    }

    /// Block-local DIF stages (`k = 15 .. 0`) on one 2^16 block: radix-4
    /// pairs (15,14) .. (5,4) with table twiddles, stride-8 vector pairs,
    /// then strides 4/2/1 in registers. Output bit-reversed within the block.
    unsafe fn dif_block_local(a: *mut u32, tb: &DifTables) {
        let blk = 1usize << BLOCK_LOG2;
        let c4_1 = bc(tb.c4[1]);
        let mut k = 15usize;
        while k >= 5 {
            let s = 1usize << k;
            let half = s / 2;
            let tab = tb.tab[k].as_ptr();
            let mut g = 0;
            while g < blk {
                let mut j = 0;
                while j < half {
                    let t1 = ld(tab.add(j)); // omega_{2s}^j
                    let t1b = avx2::mont_mul(t1, c4_1); // omega_{2s}^{j + s/2}
                    let t2 = avx2::mont_mul(t1, t1); // omega_s^j
                    let x0 = ld(a.add(g + j));
                    let x1 = ld(a.add(g + j + half));
                    let x2 = ld(a.add(g + j + s));
                    let x3 = ld(a.add(g + j + s + half));
                    let (y0, y2) = bfly(x0, x2, t1);
                    let (y1, y3) = bfly(x1, x3, t1b);
                    let (z0, z1) = bfly(y0, y1, t2);
                    let (z2, z3) = bfly(y2, y3, t2);
                    st(a.add(g + j), z0);
                    st(a.add(g + j + half), z1);
                    st(a.add(g + j + s), z2);
                    st(a.add(g + j + s + half), z3);
                    j += 8;
                }
                g += 2 * s;
            }
            k -= 2;
        }
        // k = 3: stride 8, one vector pair per group of 16, twiddle c16 lanes
        {
            let w = ld(tb.tab[3].as_ptr());
            let mut g = 0;
            while g < blk {
                let (lo, hi) = bfly(ld(a.add(g)), ld(a.add(g + 8)), w);
                st(a.add(g), lo);
                st(a.add(g + 8), hi);
                g += 16;
            }
        }
        // k = 2, 1, 0 in registers on each vector
        {
            let w4 = _mm256_set_m128i(
                _mm_loadu_si128(tb.tab[2].as_ptr() as *const __m128i),
                _mm_loadu_si128(tb.tab[2].as_ptr() as *const __m128i),
            ); // omega_8^{0..3} in both halves
            let w2 = {
                let t = tb.tab[1][1];
                _mm256_setr_epi32(1, 1, 1, t as i32, 1, 1, 1, t as i32)
            };
            let one_raw = F::ONE.raw_u32_value();
            let w2 = _mm256_setr_epi32(
                one_raw as i32,
                one_raw as i32,
                one_raw as i32,
                tb.tab[1][1] as i32,
                one_raw as i32,
                one_raw as i32,
                one_raw as i32,
                tb.tab[1][1] as i32,
            );
            let _ = w2;
            let mut g = 0;
            while g < blk {
                let v = ld(a.add(g));
                // stride 4: lanes 0-3 (lo) vs 4-7 (hi)
                let lo = _mm256_permute2x128_si256::<0x00>(v, v);
                let hi = _mm256_permute2x128_si256::<0x11>(v, v);
                let (y_lo, y_hi) = bfly(lo, hi, w4);
                let v = _mm256_permute2x128_si256::<0x20>(y_lo, y_hi);
                // stride 2: within each 128-bit half, lanes (0,1) vs (2,3); twiddle omega_4^{lane mod 2}
                let lo = _mm256_shuffle_epi32::<0b0100_0100>(v); // lanes 0,1,0,1 per half
                let hi = _mm256_shuffle_epi32::<0b1110_1110>(v); // lanes 2,3,2,3 per half
                let w = _mm256_setr_epi32(
                    one_raw as i32,
                    tb.tab[1][1] as i32,
                    one_raw as i32,
                    tb.tab[1][1] as i32,
                    one_raw as i32,
                    tb.tab[1][1] as i32,
                    one_raw as i32,
                    tb.tab[1][1] as i32,
                );
                let (y_lo, y_hi) = bfly(lo, hi, w);
                let v = _mm256_blend_epi32::<0b1100_1100>(y_lo, y_hi); // [lo0 lo1 hi0 hi1 | ...]
                                                                       // stride 1: adjacent lanes, twiddle 1
                let lo = _mm256_shuffle_epi32::<0b1010_0000>(v); // lanes 0,0,2,2
                let hi = _mm256_shuffle_epi32::<0b1111_0101>(v); // lanes 1,1,3,3
                let (y_lo, y_hi) = bfly(lo, hi, bc(one_raw));
                let v = _mm256_blend_epi32::<0b1010_1010>(y_lo, y_hi);
                st(a.add(g), v);
                g += 8;
            }
        }
    }

    /// The DIF coset LDE: two radix-16 global sweeps (k = 23 and 19) then
    /// the block-local phase; output bit-reversed per coset. `FUSED_TOP`:
    /// the input has variables 0..19 transformed and the first sweep applies
    /// the top-4 transform in registers; otherwise the input is the full
    /// monomial form. The coset scaling is always applied at the first load.
    pub fn dif_lde<const FUSED_TOP: bool>(
        input: &[u32],
        tb: &DifTables,
        worker: &Worker,
    ) -> Vec<u32> {
        assert_eq!(input.len(), N);
        let mut out: Vec<u32> = Vec::with_capacity(N);
        #[allow(clippy::uninit_vec)]
        unsafe {
            out.set_len(N)
        };
        // first sweep reads the input and writes `out` (the pass is in place on `out`
        // afterwards): copy fused into the first sweep would need an out-of-place
        // item kernel; here the first sweep loads from `input` through a cheap
        // in-place formulation: copy the item's 32 vectors then process. We keep it
        // simple: memcpy-free by running the sweep in place on a fresh copy is NOT
        // free, so the first sweep is done out of place explicitly.
        let in_addr = input.as_ptr() as usize;
        let out_addr = out.as_mut_ptr() as usize;
        let items = N / 256;
        // sweep 1 (k = 23): out-of-place: process from input into out
        worker.scope(items, |scope, geometry| {
            let (work, chunks) = (items, geometry.len());
            for idx in 0..chunks {
                let (start, size) = balanced_chunk(work, chunks, idx);
                spawn_chunk(scope, idx == chunks - 1, move |_| unsafe {
                    // copy the lines of these items, then run the in-place kernel on `out`
                    let s = 1usize << 23;
                    let sub = s / 8;
                    let lines_per_group = sub / 16;
                    for t in start..start + size {
                        let g = t / lines_per_group;
                        let jl = t % lines_per_group;
                        let base = g * 2 * s + jl * 16;
                        for m in 0..16 {
                            core::ptr::copy_nonoverlapping(
                                (in_addr as *const u32).add(base + m * sub),
                                (out_addr as *mut u32).add(base + m * sub),
                                16,
                            );
                        }
                    }
                    dif_radix16_items::<true, FUSED_TOP>(
                        out_addr as *mut u32,
                        23,
                        tb,
                        start..start + size,
                    );
                });
            }
        });
        // sweep 2 (k = 19)
        worker.scope(items, |scope, geometry| {
            let (work, chunks) = (items, geometry.len());
            for idx in 0..chunks {
                let (start, size) = balanced_chunk(work, chunks, idx);
                spawn_chunk(scope, idx == chunks - 1, move |_| unsafe {
                    dif_radix16_items::<false, false>(
                        out_addr as *mut u32,
                        19,
                        tb,
                        start..start + size,
                    );
                });
            }
        });
        // block-local
        let blocks = N >> BLOCK_LOG2;
        worker.scope(blocks, |scope, geometry| {
            let (work, chunks) = (blocks, geometry.len());
            for idx in 0..chunks {
                let (start, size) = balanced_chunk(work, chunks, idx);
                spawn_chunk(scope, idx == chunks - 1, move |_| unsafe {
                    for b in start..start + size {
                        dif_block_local((out_addr as *mut u32).add(b << BLOCK_LOG2), tb);
                    }
                });
            }
        });
        out
    }

    pub fn run() {
        use std::sync::{Arc, Barrier};
        use std::time::Instant;
        let args: Vec<String> = std::env::args().collect();
        let (mut outer, mut inner, mut cols, mut reps, mut pin) =
            (12usize, 16usize, 48usize, 1usize, true);
        let mut i = 1;
        while i < args.len() {
            match args[i].as_str() {
                "--outer" => outer = args[i + 1].parse().unwrap(),
                "--inner" => inner = args[i + 1].parse().unwrap(),
                "--cols" => cols = args[i + 1].parse().unwrap(),
                "--reps" => reps = args[i + 1].parse().unwrap(),
                "--no-pin" => {
                    pin = false;
                    i -= 1;
                }
                other => panic!("unknown arg {other}"),
            }
            i += 2;
        }
        const POOL_STACK: usize = 256 << 20;
        let lde = 2usize;
        println!("[dif] outer={outer} x inner={inner}, cols={cols} (hypercube evals 2^{LOG_N}), lde={lde}, reps={reps}, pin={pin}");
        let cpu_blocks: Vec<Vec<usize>> = if pin {
            let flat: Vec<usize> = Worker::cpu_complexes().iter().flatten().copied().collect();
            assert!(outer * inner <= flat.len());
            (0..outer)
                .map(|w| flat[w * inner..(w + 1) * inner].to_vec())
                .collect()
        } else {
            Vec::new()
        };
        let setup_worker = Worker::new_with_num_threads(outer * inner);
        let tw_full: Vec<F, Global> =
            fft::precompute_all_twiddles_for_fft_serial::<F, Global, false>(N);
        let ext_full = Avx2TwiddleExt::build_parallel(&tw_full, N, &setup_worker);
        let root = fft::domain_generator_for_size::<F>((N * lde) as u64);
        let offsets: Vec<F> =
            fft::materialize_powers_serial_starting_with_one::<F, Global>(root, lde);
        let tables: Vec<DifTables> = offsets.iter().map(|&o| DifTables::new(o)).collect();
        drop(setup_worker);
        let (tw_full, ext_full, tables, offsets) = (
            Arc::new(tw_full),
            Arc::new(ext_full),
            Arc::new(tables),
            Arc::new(offsets),
        );
        let inputs: Vec<Vec<Vec<F>>> = (0..outer)
            .map(|w| {
                (0..cols)
                    .map(|c| {
                        (0..N)
                            .map(|k| {
                                F::from_u32_with_reduction(
                                    (k as u32).wrapping_mul(2654435761)
                                        ^ ((w * cols + c) as u32).wrapping_mul(0x9E3779B9),
                                )
                            })
                            .collect()
                    })
                    .collect()
            })
            .collect();

        // correctness on one column, both cosets, both DIF variants
        {
            let w = Worker::new_with_num_threads(inner);
            let col = &inputs[0][0];
            let mono = transform_parallel(col, LOG_N, &w);
            let partial = transform_partial(col, LOG_N, 4, &w);
            // diagnostics: (1) the parallel full transform vs the serial kernel,
            // (2) partial (vars 0..19) + a scalar top-4 transform vs full
            {
                use prover::gkr::whir::hypercube_to_monomial::multivariate_hypercube_evals_into_coeffs_avx2_bb as transform_serial;
                let mut serial = col.clone();
                transform_serial(&mut serial, LOG_N);
                let d1 = serial
                    .iter()
                    .zip(mono.iter())
                    .filter(|(a, b)| a != b)
                    .count();
                let mut p2 = partial.clone();
                for b in 20..24 {
                    let stride = 1usize << b;
                    for base in (0..N).step_by(2 * stride) {
                        for j in base..base + stride {
                            let lo = p2[j];
                            p2[j + stride].sub_assign(&lo);
                        }
                    }
                }
                let d2 = p2.iter().zip(mono.iter()).filter(|(a, b)| a != b).count();
                let d3 = partial
                    .iter()
                    .zip(mono.iter())
                    .filter(|(a, b)| a != b)
                    .count();
                println!("[dif] diag: parallel-vs-serial full transform mismatches {d1}; partial+scalar-top4 vs full mismatches {d2}; partial vs full mismatches {d3}");
            }
            let mono_raw: &[u32] =
                unsafe { core::slice::from_raw_parts(mono.as_ptr() as *const u32, N) };
            let partial_raw: &[u32] =
                unsafe { core::slice::from_raw_parts(partial.as_ptr() as *const u32, N) };
            for (ci, &off) in offsets.iter().enumerate() {
                let reference = fft::baby_bear_avx2::lde_coset_avx2_parallel(
                    &mono, off, &tw_full, &ext_full, &w,
                );
                let ref_raw: &[u32] =
                    unsafe { core::slice::from_raw_parts(reference.as_ptr() as *const u32, N) };
                // the transform-separate variant validates the DIF kernel alone;
                // the top-4 fused variant then validates the partial transform +
                // in-register top transform on top of it
                for (name, mut got) in [
                    (
                        "transform-separate",
                        dif_lde::<false>(mono_raw, &tables[ci], &w),
                    ),
                    ("top-4 fused", dif_lde::<true>(partial_raw, &tables[ci], &w)),
                ] {
                    fft::bitreverse_enumeration_inplace(&mut got);
                    let mismatches = got
                        .iter()
                        .zip(ref_raw.iter())
                        .filter(|(a, b)| a != b)
                        .count();
                    assert!(mismatches == 0, "DIF {name} diverged at coset {ci}: {mismatches} of {N} elements differ (first at {:?})", got.iter().zip(ref_raw.iter()).position(|(a, b)| a != b));
                }
            }
            println!("[dif] correctness: both DIF variants == current pipeline (after bit-reversal) on {} cosets", offsets.len());
        }

        for variant in [
            "current (transform + DIT kernel)",
            "DIF top-4 fused (partial T)",
            "DIF transform-separate",
        ] {
            for mode in ["solo", "batch"] {
                let active = if mode == "solo" { 1 } else { outer };
                let barrier = Arc::new(Barrier::new(active));
                let times: Vec<f64> = std::thread::scope(|s| {
                    let handles: Vec<_> = (0..active)
                        .map(|w| {
                            let (barrier, tw_full, ext_full, tables, offsets, cpu_blocks, inputs) = (barrier.clone(), tw_full.clone(), ext_full.clone(), tables.clone(), offsets.clone(), &cpu_blocks, &inputs);
                            std::thread::Builder::new()
                                .stack_size(1 << 30)
                                .spawn_scoped(s, move || {
                                    let worker = if pin { Worker::new_with_num_threads_on_cpus_and_stack(inner, &cpu_blocks[w], POOL_STACK) } else { Worker::new_with_num_threads_and_stack(inner, POOL_STACK) };
                                    worker.pool.install(|| {
                                        let mut best = f64::MAX;
                                        for _ in 0..reps {
                                            barrier.wait();
                                            let t0 = Instant::now();
                                            let mut outs: Vec<Vec<u32>> = Vec::with_capacity(cols * lde);
                                            for col in inputs[w].iter() {
                                                if variant.starts_with("current") {
                                                    let mono = transform_parallel(col, LOG_N, &worker);
                                                    for &off in offsets.iter() {
                                                        let v = fft::baby_bear_avx2::lde_coset_avx2_parallel(&mono, off, &tw_full, &ext_full, &worker);
                                                        outs.push(unsafe { core::mem::transmute::<Vec<F>, Vec<u32>>(v) });
                                                    }
                                                } else if variant.starts_with("DIF top-4") {
                                                    let partial = transform_partial(col, LOG_N, 4, &worker);
                                                    let partial_raw: &[u32] = unsafe { core::slice::from_raw_parts(partial.as_ptr() as *const u32, N) };
                                                    for ci in 0..lde {
                                                        outs.push(dif_lde::<true>(partial_raw, &tables[ci], &worker));
                                                    }
                                                } else {
                                                    let mono = transform_parallel(col, LOG_N, &worker);
                                                    let mono_raw: &[u32] = unsafe { core::slice::from_raw_parts(mono.as_ptr() as *const u32, N) };
                                                    for ci in 0..lde {
                                                        outs.push(dif_lde::<false>(mono_raw, &tables[ci], &worker));
                                                    }
                                                }
                                            }
                                            best = best.min(t0.elapsed().as_secs_f64());
                                            std::hint::black_box(&outs);
                                            drop(outs);
                                        }
                                        best
                                    })
                                })
                                .unwrap()
                        })
                        .collect();
                    handles.into_iter().map(|h| h.join().unwrap()).collect()
                });
                let slowest = times.iter().cloned().fold(0.0, f64::max);
                let mean = times.iter().sum::<f64>() / times.len() as f64;
                println!("[dif] {variant:<34} {mode:<5} ({active:2} workers): slowest {slowest:.3} s, mean {mean:.3} s | {:.1} ms per column (both cosets) per worker", 1e3 * mean / cols as f64);
            }
        }
        println!("[dif] done");
    }
}

#[cfg(all(target_arch = "x86_64", target_feature = "avx2"))]
fn main() {
    imp::run();
}
